import { isPlatformApex, parseDatabaseHostname } from "./region.ts";

/**
 * B2 — destination-initiated PKCE for cross-origin session handoff.
 *
 * A handoff code travels in the redirect URL (short-lived, single-use, bound to
 * a destination origin). The code alone must not be redeemable: redeeming also
 * requires a secret verifier whose `SHA256` the server stored as the challenge
 * when the code was minted. The server never receives the verifier.
 *
 * The verifier is generated by, and never leaves, the **destination** origin.
 * The flow is a redirect round-trip:
 *
 *   source       ──(init, no secret)──────────────────▶ destination
 *   destination  ──(challenge, state, return)─────────▶ source
 *   source       ──(code, state)──────────────────────▶ destination
 *   destination  ──(code + verifier)──────────────────▶ API
 *
 * The destination stashes the verifier in its own origin-scoped
 * `sessionStorage`, keyed by a random `state` it also returns through the
 * source. Because the verifier is never placed in a cookie or in the URL, a
 * compromised sibling origin (for example another `*.inicontent.com` tenant)
 * cannot read a verifier for a handoff it is not part of. The challenge in the
 * URL is public (a hash), so it needs no confidentiality.
 *
 * The endpoint is restricted to platform origins: an authenticated admin runs
 * on platform origins, and the destination must never be steered to a
 * non-platform origin. A source on a tenant custom domain therefore mints
 * nothing and the user signs in at the platform host.
 */

/** Source → destination: "start a handoff". Value is the source return URL. */
export const HANDOFF_INIT_PARAM = "inicontent_handoff_init";
/** Destination → source: `base64url(SHA256(verifier))`. */
export const HANDOFF_CHALLENGE_PARAM = "inicontent_handoff_challenge";
/** Destination → source → destination: random nonce keying the verifier. */
export const HANDOFF_STATE_PARAM = "inicontent_handoff_state";
/** Destination → source: the (clean) destination URL to return to. */
export const HANDOFF_TO_PARAM = "inicontent_handoff_to";
/** Source → destination: the platform-database handoff code. */
export const HANDOFF_PLATFORM_CODE_PARAM = "inicontent_handoff";

/** Every parameter that belongs to the flow handshake (not to a minted code). */
export const HANDOFF_FLOW_PARAMS = [
	HANDOFF_INIT_PARAM,
	HANDOFF_CHALLENGE_PARAM,
	HANDOFF_STATE_PARAM,
	HANDOFF_TO_PARAM,
] as const;

/** Verifier lifetime, mirroring the server's `HANDOFF_TTL_MS` (5 minutes). */
export const HANDOFF_VERIFIER_TTL_MS = 5 * 60 * 1000;

/** SHA-256 as base64url (43 chars, no padding) — the shape of a challenge. */
const DIGEST_RE = /^[A-Za-z0-9_-]{43}$/;
const STORAGE_PREFIX = "inicontent:handoff:v:";

/**
 * The handoff-code query keys for a database: the tenant code plus the platform
 * code. `inicontent_handoff` is the platform code, never a flow parameter.
 */
export function handoffCodeParams(databaseSlug: string): string[] {
	return [
		...(databaseSlug !== "inicontent" ? [`${databaseSlug}_handoff`] : []),
		HANDOFF_PLATFORM_CODE_PARAM,
	];
}

/** A well-formed `base64url(SHA256(verifier))` challenge. */
export function isHandoffChallenge(value: unknown): value is string {
	return typeof value === "string" && DIGEST_RE.test(value);
}

/**
 * Whether an origin is a platform origin the handoff may bounce through: the
 * bare or `www` platform host, or `https://<slug>.inicontent.com`. Custom
 * domains are refused, so the destination cannot be redirected off-platform.
 */
export function isPlatformHandoffOrigin(origin: string): boolean {
	if (typeof origin !== "string" || !origin) return false;
	let url: URL;
	try {
		url = new URL(origin);
	} catch {
		return false;
	}
	if (url.protocol !== "https:") return false;
	// Reject anything that is not a bare origin (path/query/hash/credentials/port).
	if (url.port || url.origin !== origin) return false;
	const host = url.hostname;
	return isPlatformApex(host) || !!parseDatabaseHostname(host);
}

/** base64url without padding, matching the API's `digest("base64url")`. */
function base64Url(bytes: Uint8Array): string {
	let binary = "";
	for (const byte of bytes) binary += String.fromCharCode(byte);
	return btoa(binary)
		.replace(/\+/g, "-")
		.replace(/\//g, "_")
		.replace(/=+$/, "");
}

/**
 * A fresh verifier/challenge pair. The verifier is a 256-bit secret; the
 * challenge is `base64url(SHA256(verifier))`. A new pair is generated per
 * handoff by the destination.
 */
export async function createHandoffPkce(): Promise<{
	verifier: string;
	challenge: string;
}> {
	const verifier = base64Url(crypto.getRandomValues(new Uint8Array(32)));
	const digest = await crypto.subtle.digest(
		"SHA-256",
		new TextEncoder().encode(verifier),
	);
	return { verifier, challenge: base64Url(new Uint8Array(digest)) };
}

/** A fresh 128-bit nonce used to key a verifier across the redirect. */
export function newHandoffState(): string {
	return base64Url(crypto.getRandomValues(new Uint8Array(16)));
}

export interface HandoffVerifierRecord {
	verifier: string;
	/** Origin that generated the verifier and will redeem the code. */
	destination: string;
	/** Clean destination URL the source returns to once the code is minted. */
	to: string;
	/** `Date.now()` when stored, for a bounded in-browser lifetime. */
	createdAt: number;
}

function sessionStore(): Storage | null {
	try {
		return typeof sessionStorage === "undefined" ? null : sessionStorage;
	} catch {
		// Sandboxed/blocked storage throws on access.
		return null;
	}
}

/** `sessionStorage` key under which a state's verifier lives. */
export function handoffVerifierStorageKey(state: string): string {
	return `${STORAGE_PREFIX}${state}`;
}

/** Persist a verifier on the destination origin, keyed by the flow state. */
export function storeHandoffVerifier(
	state: string,
	record: Omit<HandoffVerifierRecord, "createdAt">,
): void {
	const store = sessionStore();
	if (!store || !state) return;
	try {
		store.setItem(
			handoffVerifierStorageKey(state),
			JSON.stringify({ ...record, createdAt: Date.now() }),
		);
	} catch {
		// Quota/blocked storage: the flow degrades to a signed-out landing.
	}
}

/** Read a live verifier by state, or null when absent, malformed or expired. */
export function readHandoffVerifier(
	state: string,
): HandoffVerifierRecord | null {
	const store = sessionStore();
	if (!store || !state) return null;
	try {
		const raw = store.getItem(handoffVerifierStorageKey(state));
		if (!raw) return null;
		const parsed = JSON.parse(raw) as Partial<HandoffVerifierRecord>;
		if (
			typeof parsed?.verifier !== "string" ||
			!parsed.verifier ||
			typeof parsed?.destination !== "string" ||
			typeof parsed?.createdAt !== "number" ||
			Date.now() - parsed.createdAt > HANDOFF_VERIFIER_TTL_MS
		) {
			store.removeItem(handoffVerifierStorageKey(state));
			return null;
		}
		return {
			verifier: parsed.verifier,
			destination: parsed.destination,
			to: typeof parsed.to === "string" ? parsed.to : "",
			createdAt: parsed.createdAt,
		};
	} catch {
		return null;
	}
}

/** Drop a spent (or unusable) verifier so it cannot be replayed. */
export function clearHandoffVerifier(state: string): void {
	const store = sessionStore();
	if (!store || !state) return;
	try {
		store.removeItem(handoffVerifierStorageKey(state));
	} catch {
		// Nothing to do: the entry expires on its own.
	}
}

/**
 * The current source URL with its fragment and every handoff parameter
 * removed, or null outside a browser. This is what the source hands the
 * destination so it can bounce the browser back.
 */
export function handoffSourceUrl(): string | null {
	if (typeof location === "undefined") return null;
	try {
		const url = new URL(location.href);
		url.hash = "";
		for (const key of HANDOFF_FLOW_PARAMS) url.searchParams.delete(key);
		return url.toString();
	} catch {
		return null;
	}
}

/** The destination's own clean URL (no query/fragment) to return to. */
export function handoffDestinationReturnUrl(): string | null {
	if (typeof location === "undefined") return null;
	return `${location.origin}${location.pathname}`;
}

/** Remove every handoff parameter (flow + codes) from a query object. */
export function stripHandoffParams<T extends Record<string, unknown>>(
	query: T,
	databaseSlug: string,
): T {
	const drop = new Set<string>([
		...HANDOFF_FLOW_PARAMS,
		...handoffCodeParams(databaseSlug),
	]);
	const next = { ...query };
	for (const key of drop) delete (next as Record<string, unknown>)[key];
	return next;
}
